new:
        assert!(matches!(stale, Err(TimelineAuthoringError::Stale { .. })));
    }

    #[test]
    fn granular_sequencer_commands_share_one_transaction_and_undo_boundary() {
        let track_id = TimelineTrackId::generate();
        let clip_id = TimelineClipId::generate();
        let duplicate_id = TimelineClipId::generate();
        let mut doc = TimelineDocument::new("sequence", TimelineTick::new(100));
        doc.tracks.push(TimelineTrack {
            id: track_id.clone(),
            name: "transform".into(),
            kind: TimelineTrackKind::TransformProperty,
            enabled: true,
            priority: 1,
            binding: Some(TimelineBinding::Entity {
                entity: crate::EntityId::generate(),
            }),
            clips: vec![TimelineClip {
                id: clip_id.clone(),
                name: "move".into(),
                start: TimelineTick::ZERO,
                duration: TimelineTick::new(20),
                source_offset: TimelineTick::ZERO,
                blend: TimelineBlend::default(),
                payload: TimelineClipPayload::TransformProperty {
                    property: "engine.transform.translation".into(),
                    keys: vec![TimelinePropertyKey {
                        tick: TimelineTick::ZERO,
                        value: TimelinePropertyValue::Vec3([0.0, 0.0, 0.0]),
                    }],
                },
            }],
        });
        let mut service = TimelineAuthoringService::new(doc).unwrap();
        let base = service.inspect(&writable()).unwrap();
        let applied = service
            .apply_commands(
                &writable(),
                base.revision,
                base.generation,
                vec![
                    TimelineAuthoringCommand::SetTrackPriority {
                        track: track_id.clone(),
                        priority: 9,
                    },
                    TimelineAuthoringCommand::SetPropertyKey {
                        clip: clip_id.clone(),
                        key: TimelinePropertyKey {
                            tick: TimelineTick::new(10),
                            value: TimelinePropertyValue::Vec3([10.0, 0.0, 0.0]),
                        },
                    },
                    TimelineAuthoringCommand::DuplicateClip {
                        clip: clip_id.clone(),
                        duplicate: duplicate_id.clone(),
                        start: TimelineTick::new(20),
                    },
                ],
            )
            .unwrap();
        assert!(applied.success);
        let track = &service.document().tracks[0];
        assert_eq!(track.priority, 9);
        assert_eq!(track.clips.len(), 2);
        assert_eq!(track.clips[1].id, duplicate_id);
        let TimelineClipPayload::TransformProperty { keys, .. } = &track.clips[0].payload else {
            panic!("expected Transform/Property clip");
        };
        assert_eq!(keys.len(), 2);

        assert!(service.undo());
        assert_eq!(service.document().tracks[0].priority, 1);
        assert_eq!(service.document().tracks[0].clips.len(), 1);
        assert!(service.redo());
        assert_eq!(service.document().tracks[0].priority, 9);
        assert_eq!(service.document().tracks[0].clips.len(), 2);
    }
